34:async function getJson(
35:  url: string,
36:  opts: ProbeOptions,
37:): Promise<{ status: number; body: unknown } | null> {
38:  const doFetch = opts.fetchImpl ?? fetch;
39:  const timeout = AbortSignal.timeout(opts.timeoutMs ?? 8_000);
40:  try {
41:    const res = await doFetch(url, {
42:      signal: timeout,
43:      headers: { accept: "application/json" },
44:    });
45:    let body: unknown = null;
46:    try {
47:      body = await res.json();
48:    } catch {
49:      // A body we cannot read is not evidence about the posting. Keeping the
50:      // status and dropping the body lets the caller decide, and the caller
51:      // treats "200 that is not the posting we asked for" as unknown.
52:      body = null;
53:    }
54:    return { status: res.status, body };
55:  } catch {
56:    return null;
57:  }
58:}
