146:/**
147: * Is `current` a DIFFERENT posting from `approved`?
148: *
149: * False whenever the question cannot be answered — a URL with no id, two
150: * different ATSes, anything unparseable. The guard this feeds refuses a
151: * submission, so it must only fire on evidence, never on ignorance: a false
152: * positive blocks a good application, and there is no shortage of legitimate
153: * reasons for a URL to change mid-apply (a redirect to an apply subdomain, a
154: * new tab, a step token appended).
155: */
156:export function isDifferentPosting(
157:  approved: string | null | undefined,
158:  current: string | null | undefined,
159:): boolean {
160:  const a = postingIdentity(approved);
161:  const b = postingIdentity(current);
162:  if (!a || !b) return false;
163:  if (a.family !== b.family) return false;
164:  return a.id !== b.id;
165:}

